begin;
create extension if not exists pgtap with schema extensions;
select plan(20);
insert into auth.users(id,email) values('b1111111-1111-4111-8111-111111111111','blog-admin-rls@example.test'),('b2222222-2222-4222-8222-222222222222','blog-reader-rls@example.test');
insert into public.admin_users(user_id) values('b1111111-1111-4111-8111-111111111111');
insert into public.blog_articles select (jsonb_populate_record(null::public.blog_articles,to_jsonb(a) || jsonb_build_object('id','b3333333-3333-4333-8333-333333333333','slug','rls-blog-draft','status','draft','is_indexable',false,'date_published',null,'related_articles','[]'::jsonb))).* from public.blog_articles a where a.slug='create-ai-photos-with-chatgpt';
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select is((select count(*)::integer from public.blog_articles where slug='rls-blog-draft'),0,'Anonymous cannot read drafts');
select is((select count(*)::integer from public.blog_articles where slug='qa-blog-direct'),1,'Anonymous can read normal published articles');
select throws_ok($$insert into public.blog_authors values('forbidden','Forbidden','Forbidden','/about')$$,'42501',null,'Anonymous cannot write editorial content');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','b2222222-2222-4222-8222-222222222222',true);
select is((select count(*)::integer from public.blog_articles where slug='rls-blog-draft'),0,'Ordinary authenticated user cannot read drafts');
select throws_ok($$insert into public.blog_authors values('forbidden','Forbidden','Forbidden','/about')$$,'42501',null,'Ordinary user cannot write editorial content');
select set_config('request.jwt.claim.sub','b1111111-1111-4111-8111-111111111111',true);
select is((select count(*)::integer from public.blog_articles where slug='rls-blog-draft'),1,'Admin can read drafts');
select lives_ok($$update public.blog_articles set title='Edited RLS guide' where slug='rls-blog-draft'$$,'Admin can edit a private article');
select lives_ok($$update public.blog_articles set status='published',is_indexable=true where slug='rls-blog-draft'$$,'Normal publication accepts indexability and sets publication date');
select ok((select date_published is not null from public.blog_articles where slug='rls-blog-draft'),'First publication date exists');
update public.blog_articles set related_articles=array_append(related_articles,'rls-blog-draft') where slug='keep-your-face-the-same-in-ai-photos';
select lives_ok($$update public.blog_articles set slug='rls-blog-moved' where slug='rls-blog-draft'$$,'Published URL move succeeds');
select is((select article_id::text from public.blog_redirects where old_slug='rls-blog-draft'),'b3333333-3333-4333-8333-333333333333','URL history is transactional');
select ok((select 'rls-blog-moved'=any(related_articles) from public.blog_articles where slug='keep-your-face-the-same-in-ai-photos'),'Related article links follow the canonical move');
select ok((select not 'rls-blog-draft'=any(related_articles) from public.blog_articles where slug='keep-your-face-the-same-in-ai-photos'),'Old related slug is removed transactionally');
select throws_ok($$update public.blog_articles set slug='qa-blog-direct' where slug='rls-blog-moved'$$,'23505',null,'Duplicate canonical slug is rejected');
select throws_ok($$update public.blog_articles set is_indexable=false,noindex_reason='Temporary',noindex_review_at=now()+interval '31 days' where slug='rls-blog-moved'$$,'P0001',null,'Unbounded noindex is rejected');
select throws_ok($$update public.blog_articles set is_indexable=false,noindex_reason=null,noindex_review_at=now()+interval '1 day' where slug='rls-blog-moved'$$,'23514',null,'Noindex without a reason is rejected');
select lives_ok($$update public.blog_articles set is_indexable=false,noindex_reason='Review source',noindex_review_at=now()+interval '1 day' where slug='rls-blog-moved'$$,'Temporary exception with reason and deadline succeeds');
reset role;
-- Simulate passage of time; the application cannot write an expired deadline.
alter table public.blog_articles disable trigger blog_article_history;
update public.blog_articles set noindex_review_at=now()-interval '1 day' where slug='rls-blog-moved';
alter table public.blog_articles enable trigger blog_article_history;
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select is((select count(*)::integer from public.blog_articles where slug='rls-blog-moved'),0,'Expired exception is publicly inaccessible');
select is((select count(*)::integer from public.blog_redirects where old_slug='rls-blog-draft'),0,'Expired exception redirect cannot expose the article');
reset role;
select lives_ok($$update public.blog_articles set status='review',is_indexable=false where slug='rls-blog-moved'$$,'An overdue exception can return to private review');
select * from finish();
rollback;
